BEGIN;
-- PT114-S1-Q6
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND q.stimulus=$batch01$Every year, new reports appear concerning the health risks posed by certain substances, such as coffee and sugar. One year an article claimed that coffee is dangerous to one’s health. The next year, another article argued that coffee has some benefits for one’s health. From these contradictory opinions, we see that experts are useless for guiding one’s decisions about one’s health.$batch01$ AND q.prompt=$batch01$Which one of the following most accurately describes a flaw in the argument above?$batch01$ AND q.correct_choice=$batch01$E$batch01$) THEN RAISE EXCEPTION 'Question changed: PT114-S1-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S1-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$The argument takes for granted that coffee is dangerous to one’s health.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$The argument presumes, without providing warrant, that one always wants expert guidance in making decisions about one’s health.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$The argument fails to consider the nature of expert opinion in areas other than health.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$The argument presumes, without providing justification, that because expert opinion is trustworthy in one case, it must therefore be trustworthy in all cases.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$The argument fails to consider that coffee may be harmful to one’s health in some respects and beneficial in others.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT114-S1-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Experts are useless for guiding health decisions.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$One article called coffee dangerous, while another said coffee has some health benefits.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Are the articles actually incompatible? A substance can harm health in one respect and help in another. Both experts could be right and useful: their advice may identify different effects that a decision maker should weigh. Even a genuine disagreement about coffee would be thin support for declaring all experts useless.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the reconciliation of coffee's harms and benefits that dissolves the supposed contradiction.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The speaker presents one article as saying coffee is dangerous and another as saying it has benefits. He does not adopt the first article's conclusion as a premise.$batch01$), ($batch01$B$batch01$, $batch01$The argument says expert guidance is useless, whether or not people always want such guidance. A desire for advice is not the logical bridge at issue.$batch01$), ($batch01$C$batch01$, $batch01$The conclusion is about health decisions, so expert opinion in other areas cannot repair or expose the coffee-based inference.$batch01$), ($batch01$D$batch01$, $batch01$The author is skeptical of experts. He does not infer that all expert opinions are trustworthy because one is.$batch01$), ($batch01$E$batch01$, $batch01$Coffee could be harmful in some respects and beneficial in others. The articles would then report different true facts, not contradictory advice. The argument's starting point for dismissing experts would fail.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
